import { getPermissions } from "@/common/Permissions";

import { usePermissions } from "@/context/PermissionContext";

import { useCurrentFacilitySilently } from "@/pages/Facility/utils/useCurrentFacility";

import { ValueSetScope } from "@/types/valueSet/valueSet";

/**
 * Whether the current user may create or edit value sets in `scope` — the
 * single gate for the list's Create button, the editor's save and the
 * departments field.
 *
 * Facility mounts gate on the facility's *object* permissions (the backend
 * checks `can_write_valueset` in the facility's root organization); the
 * admin mount falls back to the user's own permission union, since no
 * object-scoped permissions apply to an instance-wide list.
 *
 * `isLoading` is true while the facility (and its permissions) is still
 * being fetched on a facility mount, so callers can hold a skeleton instead
 * of flashing a denied state.
 */
export function useCanWriteValueSet(scope: ValueSetScope): {
  canWrite: boolean;
  isLoading: boolean;
} {
  const { hasPermission, userPermissions } = usePermissions();
  const { facility, isFacilityLoading } = useCurrentFacilitySilently();

  const { canWriteValueSet } = getPermissions(
    hasPermission,
    scope.authContext === "facility"
      ? (facility?.permissions ?? [])
      : userPermissions,
  );

  return {
    canWrite: canWriteValueSet,
    // Track the fetch, not data presence — a user who cannot read the
    // facility (404) would otherwise leave `!facility` true forever.
    isLoading: scope.authContext === "facility" && isFacilityLoading,
  };
}

import { useQuery } from "@tanstack/react-query";

import {
  ValueSetAuthContext,
  ValueSetRead,
  ValueSetStatus,
} from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import query from "@/Utils/request/query";

export interface ScopedValueSet {
  valueset: ValueSetRead;
  /** Which list the set came from. `ValueSetReadSpec` does not return
   *  `auth_context`, so this is the only scope signal the UI has. */
  authContext: Extract<ValueSetAuthContext, "instance" | "facility">;
}

const PAGE = 50;

/**
 * Active value sets a picker inside `facilityId` (or the admin area, when
 * undefined) may choose from: the instance-level sets, plus — inside a
 * facility — that facility's own sets, listed first. Two requests because
 * the list endpoint filters by either `auth_context` or `facility` and its
 * read spec carries neither back.
 */
export function useScopedValueSets({
  facilityId,
  search,
}: {
  facilityId?: string;
  search: string;
}): { options: ScopedValueSet[]; isFetching: boolean } {
  const params = {
    name: search || undefined,
    status: ValueSetStatus.ACTIVE,
    limit: PAGE,
  };

  const instance = useQuery({
    queryKey: ["valuesets", "scoped", "instance", search],
    queryFn: query.debounced(valueSetApi.list, {
      queryParams: { ...params, auth_context: "instance" },
    }),
  });

  const facility = useQuery({
    queryKey: ["valuesets", "scoped", "facility", facilityId, search],
    queryFn: query.debounced(valueSetApi.list, {
      queryParams: { ...params, facility: facilityId },
    }),
    enabled: !!facilityId,
  });

  const options: ScopedValueSet[] = [
    ...(facility.data?.results ?? []).map((valueset) => ({
      valueset,
      authContext: "facility" as const,
    })),
    ...(instance.data?.results ?? []).map((valueset) => ({
      valueset,
      authContext: "instance" as const,
    })),
  ];

  return {
    options,
    isFetching: instance.isFetching || facility.isFetching,
  };
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";

import FacilityOrganizationSelector from "@/pages/Facility/settings/organizations/components/FacilityOrganizationSelector";

import valueSetApi from "@/types/valueSet/valueSetApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";

interface ValueSetOrganizationsFieldProps {
  facilityId: string;
  valuesetId: string;
  canWrite: boolean;
}

export const valueSetOrganizationsKey = (valuesetId: string) =>
  ["valueset", valuesetId, "facility-organizations"] as const;

/**
 * Departments that can see and use a facility value set. A facility set
 * with no departments is visible to superusers only (the backend gates
 * reads on organization membership), so this is the first thing to fill in
 * after creating one.
 *
 * The organizations endpoints 403 for anything but a facility-context set;
 * a user's own set listed under the same facility therefore renders
 * nothing here rather than an error.
 */
export function ValueSetOrganizationsField({
  facilityId,
  valuesetId,
  canWrite,
}: ValueSetOrganizationsFieldProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const { data: current, isError } = useQuery({
    queryKey: valueSetOrganizationsKey(valuesetId),
    queryFn: query(valueSetApi.getFacilityOrganizations, {
      pathParams: { id: valuesetId },
      silent: true,
    }),
  });

  const { mutate: setFacilityOrganizations } = useMutation({
    mutationFn: mutate(valueSetApi.setFacilityOrganizations, {
      pathParams: { id: valuesetId },
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: valueSetOrganizationsKey(valuesetId),
      });
      toast.success(t("organizations_updated"));
    },
  });

  if (isError) {
    return null;
  }

  const currentIds = current?.results.map((org) => org.id) ?? [];

  return (
    <div className="space-y-2">
      <p className="text-sm font-medium text-gray-800">
        {t("departments_with_access")}
      </p>
      <p className="text-sm text-gray-500">
        {t("departments_with_access_hint")}
      </p>
      {canWrite ? (
        <FacilityOrganizationSelector
          facilityId={facilityId}
          value={currentIds}
          currentOrganizations={current?.results}
          optional
          onChange={(ids) =>
            setFacilityOrganizations({ facility_organizations: ids ?? [] })
          }
        />
      ) : (
        <div className="flex flex-wrap items-center gap-2 rounded-md border border-gray-200 p-1.5">
          {currentIds.length === 0 && (
            <p className="px-1.5 py-1 text-sm text-gray-500">
              {t("no_departments_assigned")}
            </p>
          )}
          {current?.results.map((org) => (
            <Badge key={org.id} variant="secondary">
              {org.name}
            </Badge>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { useTranslation } from "react-i18next";

import Autocomplete from "@/components/ui/autocomplete";

import { ValueSetRead } from "@/types/valueSet/valueSet";
import { mergeAutocompleteOptions } from "@/Utils/utils";

import { ScopedValueSet, useScopedValueSets } from "./useScopedValueSets";

interface ValueSetParentPickerProps {
  facilityId: string;
  /** The current parent — may come from outside the loaded pages (e.g. a
   *  `?parent=` deep link), so it is merged into the options by identity. */
  value?: ValueSetRead;
  onChange: (parent: ScopedValueSet | undefined) => void;
  disabled?: boolean;
  id?: string;
  "aria-labelledby"?: string;
}

/**
 * Picks the value set a new facility set extends: the instance sets plus
 * this facility's own, each labelled with where it lives so two sets that
 * share a name (an instance set and a facility override of it) stay
 * distinguishable.
 */
export function ValueSetParentPicker({
  facilityId,
  value,
  onChange,
  disabled,
  ...ariaProps
}: ValueSetParentPickerProps) {
  const { t } = useTranslation();
  const [search, setSearch] = useState("");
  const { options, isFetching } = useScopedValueSets({ facilityId, search });

  const scopeLabel = (option: ScopedValueSet) =>
    `${option.valueset.name} (${t(option.authContext === "facility" ? "this_facility" : "instance")})`;

  const autocompleteOptions = mergeAutocompleteOptions(
    options.map((option) => ({
      label: scopeLabel(option),
      value: option.valueset.id,
    })),
    value ? { label: value.name, value: value.id } : undefined,
  );

  return (
    <Autocomplete
      {...ariaProps}
      options={autocompleteOptions}
      value={value?.id ?? ""}
      onChange={(id) =>
        onChange(options.find((option) => option.valueset.id === id))
      }
      onSearch={setSearch}
      isLoading={isFetching}
      disabled={disabled}
      placeholder={t("none")}
      noOptionsMessage={t("no_valuesets_found")}
    />
  );
}

