export function ValueSetList({ scope }: { scope: ValueSetScope }) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { canWrite } = useCanWriteValueSet(scope);
  const { qParams, updateQuery, Pagination, resultsPerPage } = useFilters({
    limit: 15,
    disableCache: true,
  });

  // The admin area only ever lists instance sets; inside a facility the
  // Instance tab is a read-only catalogue of what can be customized.
  const source: Source =
    scope.authContext === "facility" && qParams.source !== "instance"
      ? "facility"
      : "instance";

  const { data: response, isLoading } = useQuery({
    queryKey: ["valuesets", scope.authContext, scope.facilityId, qParams],
    queryFn: query.debounced(valueSetApi.list, {
      queryParams: {
        limit: resultsPerPage,
        offset: ((qParams.page || 1) - 1) * resultsPerPage,
        name: qParams.name,
        status: qParams.status || ValueSetStatus.ACTIVE,
        ...(source === "facility"
          ? { facility: scope.facilityId }
          : { auth_context: "instance" }),
      },
    }),
  });

  const valuesets = response?.results || [];

  const renderActions = (valueset: ValueSetRead) => {
    if (source === "instance" && scope.authContext === "facility") {
      // Instance sets are not editable from a facility (the backend
      // reserves them for superusers) — inspect, or customize a copy.
      return (
        <>
          <ValueSetPreview
            valueset={valueset}
            trigger={
              <Button variant="outline" size="sm">
                <Eye className="size-4 mr-0" />
                {t("preview")}
              </Button>
            }
          />
          {canWrite && (
            <Button
              variant="outline"
              size="sm"
              onClick={() =>
                navigate(`${scope.basePath}/create?parent=${valueset.id}`)
              }
            >
              <Copy className="size-4 mr-0" />
              {t("customize")}
            </Button>
          )}
        </>
      );
    }
    const readOnly = valueset.is_system_defined || !canWrite;
    return (
      <Button
        variant="outline"
        size="sm"
        onClick={() => navigate(`${scope.basePath}/${valueset.id}/edit`)}
        className="hover:bg-primary/5"
      >
        {readOnly ? (
          <>
            <Eye className="size-4 mr-0" />
            {t("view")}
          </>
        ) : (
          <>
            <Pencil className="size-4 mr-0" />
            {t("edit")}
          </>
        )}
      </Button>
    );
  };

  const rowsProps: RowsProps = {
    valuesets,
    isLoading,
    emptyMessage:
      source === "facility"
        ? t("no_facility_valuesets")
        : t("adjust_valueset_filters"),
    renderActions,
  };

  return (
    <div className="container mx-auto px-4 py-6">
      <div className="mb-4 px-4 md:px-0">
        <div className="mb-2">
          <h1 className="text-2xl font-bold">{t("valuesets")}</h1>
          <p className="text-gray-600">
            {scope.authContext === "facility"
              ? t("manage_facility_valuesets")
              : t("manage_and_view_valuesets")}
          </p>
        </div>

        {scope.authContext === "facility" && (
          <Tabs
            value={source}
            onValueChange={(value) =>
              updateQuery({
                source: value === "instance" ? value : undefined,
                page: undefined,
              })
            }
            className="mt-6"
          >
            <TabsList aria-label={t("source")}>
              <TabsTrigger value="facility">{t("this_facility")}</TabsTrigger>
              <TabsTrigger value="instance">{t("instance")}</TabsTrigger>
            </TabsList>
          </Tabs>
        )}

        <div className="mt-8 mb-4">
          <div className="w-full overflow-x-auto pb-1">
            <Tabs
              defaultValue="active"
              value={qParams.status || "active"}
              onValueChange={(value) => updateQuery({ status: value })}
            >
              <div className="min-w-[480px]">
                <TabsList className="flex w-full">
                  {valuesOf(ValueSetStatus).map((status) => {
                    const IconComponent = VALUESET_STATUS_ICONS[status];
                    return (
                      <TabsTrigger
                        key={status}
                        value={status}
                        className="flex-1"
                      >
                        <IconComponent className="size-4" />
                        {t(status)}
                      </TabsTrigger>
                    );
                  })}
                </TabsList>
              </div>
            </Tabs>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="relative w-full sm:max-w-md">
            <Search className="absolute left-2 top-2.5 size-4 text-gray-500" />
            <Input
              placeholder={t("search_valuesets")}
              className="pl-10 w-full"
              value={qParams.name || ""}
              onChange={(e) => updateQuery({ name: e.target.value })}
            />
          </div>

          {canWrite && source === "facility" && (
            <Button className="w-full sm:w-auto">
              <Link
                href={`${scope.basePath}/create`}
                className="flex items-center gap-2"
              >
                <PlusIcon className="size-4" />
                {t("create_valueset")}
              </Link>
            </Button>
          )}
          {canWrite && scope.authContext === "instance" && (
            <Button className="w-full sm:w-auto">
              <Link
                href={`${scope.basePath}/create`}
                className="flex items-center gap-2"
              >
                <PlusIcon className="size-4" />
                {t("create_valueset")}
              </Link>
            </Button>
          )}
        </div>
      </div>
      <RenderTable {...rowsProps} />
      <RenderCard {...rowsProps} />
      <Pagination totalCount={response?.count ?? 0} />
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { t } from "i18next";
import { useEffect, useState } from "react";

import CareIcon from "@/CAREUI/icons/CareIcon";

import Autocomplete from "@/components/ui/autocomplete";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";

import { ValueSetEditor } from "@/components/ValueSet/ValueSetEditor";
import { useScopedValueSets } from "@/components/ValueSet/useScopedValueSets";

import {
  INSTANCE_VALUESET_SCOPE,
  ValueSetConfig,
  ValueSetRead,
  ValueSetScope,
  valueSetBinding,
} from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import query from "@/Utils/request/query";
import { mergeAutocompleteOptions } from "@/Utils/utils";

interface CreateValueSetProps {
  onValueSetChange?: (valueSet: ValueSetConfig) => void;
  value?: ValueSetConfig;
  /** Where the host is mounted. Inside a facility the picker lists that
   *  facility's sets alongside the instance ones, and the inline "Create
   *  value set" sheet files under the facility — only superusers may
   *  create instance-context sets. */
  scope?: ValueSetScope;
}

export function SelectOrCreateValueset({
  onValueSetChange,
  value,
  scope = INSTANCE_VALUESET_SCOPE,
}: CreateValueSetProps) {
  const [isSheetOpen, setIsSheetOpen] = useState(false);
  const [currentValueSet, setCurrentValueSet] = useState<ValueSetRead>();
  const [searchQuery, setSearchQuery] = useState("");

  const { options, isFetching: isFetchingValuesets } = useScopedValueSets({
    facilityId: scope.facilityId,
    search: searchQuery,
  });

  // An imported questionnaire may reference a valueset by slug alone, and
  // expand_slug is the only endpoint that maps one back to its valueset.
  const { data: valuesetById, isLoading: isLoadingById } = useQuery({
    queryKey: ["valueset", value?.external_id],
    queryFn: query(valueSetApi.get, {
      pathParams: { id: value?.external_id ?? "" },
    }),
    enabled: !!value?.external_id,
  });

  // Slug-only references are instance-level by contract (see
  // valueSetBinding), so this resolves without a facility on purpose.
  const { data: valuesetBySlug, isLoading: isLoadingBySlug } = useQuery({
    queryKey: ["valueset", "by-slug", value?.slug],
    queryFn: query(valueSetApi.expandSlug, {
      body: { slug: value?.slug ?? "", search: "", count: 1 },
    }),
    enabled: !value?.external_id && !!value?.slug,
  });

  const isLoadingCurrent = isLoadingById || isLoadingBySlug;

  useEffect(() => {
    const resolved = valuesetById ?? valuesetBySlug?.valueset;
    resolved && setCurrentValueSet(resolved);
  }, [valuesetById, valuesetBySlug]);

  // Labels carry the scope only where two lists are merged — an instance
  // set and a facility override of it usually share a name.
  const labelFor = (name: string, authContext: "instance" | "facility") =>
    scope.authContext === "facility"
      ? `${name} (${t(authContext === "facility" ? "this_facility" : "instance")})`
      : name;

  const valueSetOptions = options.map((option) => ({
    label: labelFor(option.valueset.name, option.authContext),
    value: option.valueset.id,
  }));

  const handleValueSetChange = (selectedId: string) => {
    const selected = options.find(
      (option) => option.valueset.id === selectedId,
    );
    if (selected) {
      onValueSetChange?.(
        valueSetBinding(selected.valueset, selected.authContext),
      );
      return;
    }
    // Re-picking the current (merged-in) entry keeps the stored reference
    // as is — its binding was decided when it was first chosen.
    if (currentValueSet?.id === selectedId && value) {
      onValueSetChange?.(value);
    }
  };

  return (
    <div className="space-y-1.5">
      <div className="flex items-center gap-2 flex-col sm:flex-row">
        <div className="w-full">
          <Autocomplete
            options={mergeAutocompleteOptions(
              valueSetOptions,
              currentValueSet
                ? {
                    label: labelFor(
                      currentValueSet.name,
                      value?.external_id ? "facility" : "instance",
                    ),
                    value: currentValueSet.id,
                  }
                : undefined,
            )}
            value={value?.external_id ?? currentValueSet?.id ?? ""}
            onChange={handleValueSetChange}
            onSearch={setSearchQuery}
            placeholder={t("select_a_value_set")}
            isLoading={isFetchingValuesets || isLoadingCurrent}
            noOptionsMessage={t("no_valuesets_found")}
          />
        </div>
        <Sheet open={isSheetOpen} onOpenChange={setIsSheetOpen}>
          <SheetTrigger asChild>
            <Button variant="outline" className="gap-2 w-full sm:w-auto">
