import { faker } from "@faker-js/faker";
import { expect, test } from "@playwright/test";
import { adminApiHeaders, apiBaseUrl } from "tests/helper/questionnaireV2";
import { expectToast } from "tests/helper/ui";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

/** Removes this facility's value sets with `slug` so the per-facility slug
 *  uniqueness constraint cannot trip a re-run (the DB is not reset between
 *  local runs). Soft-deleted rows no longer count towards it. */
async function deleteFacilityValueSetsBySlug(facilityId: string, slug: string) {
  const res = await fetch(
    `${apiBaseUrl()}/api/v1/valueset/?facility=${facilityId}&limit=100`,
    { headers: adminApiHeaders() },
  );
  const body = (await res.json()) as { results: { id: string; slug: string }[] };
  for (const valueset of body.results.filter((vs) => vs.slug === slug)) {
    await fetch(`${apiBaseUrl()}/api/v1/valueset/${valueset.id}/`, {
      method: "DELETE",
      headers: adminApiHeaders(),
    });
  }
}

test.describe("Facility value sets", () => {
  let facilityId: string;
  let basePath: string;

  test.beforeEach(async ({ page }) => {
    facilityId = getFacilityId();
    basePath = `/facility/${facilityId}/settings/valuesets`;
    await page.goto(basePath);
  });

  test("create a facility value set and land on its edit page with departments", async ({
    page,
  }) => {
    const name = `Facility VS ${faker.word.words(2)} ${Date.now()}`;
    const description = faker.lorem.sentence();

    await test.step("List shows both sources and a create action", async () => {
      await expect(
        page.getByRole("heading", { name: "ValueSets", level: 1 }),
      ).toBeVisible();
      await expect(page.getByRole("tab", { name: "This facility" })).toBeVisible();
      await expect(page.getByRole("tab", { name: "Instance" })).toBeVisible();
      await page.getByRole("link", { name: "Create ValueSet" }).click();
      await page.waitForURL(/\/settings\/valuesets\/create$/);
    });

    await test.step("Fill the form; lineage is offered but stays off", async () => {
      await page.getByRole("textbox", { name: "Name *" }).fill(name);
      await page
        .getByRole("textbox", { name: "Description" })
        .fill(description);
      await expect(page.getByText("Based on", { exact: true })).toBeVisible();
      await expect(
        page.getByRole("switch", { name: "Replace the parent in this facility" }),
      ).toBeDisabled();

      await page.getByRole("button", { name: "Add Rule" }).first().click();
      await page.getByRole("combobox", { name: "System" }).click();
      await page.getByRole("option", { name: "SNOMED" }).click();
      await page.getByRole("button", { name: "Add Concept" }).click();
      await page.getByRole("textbox", { name: "Code" }).fill("386661006");
      await page.getByLabel("Verify code").click();
      await expect(
        page
          .getByRole("listitem")
          .filter({ hasText: "Code verified successfully" }),
      ).toBeVisible();
    });

    await test.step("Save lands on the edit page, where departments are set", async () => {
      await page.getByRole("button", { name: "Save ValueSet" }).click();
      await expectToast(page, /valueset created successfully/i);
      await page.waitForURL(/\/settings\/valuesets\/[0-9a-f-]+\/edit$/);
      await expect(page.getByText("Departments with access")).toBeVisible();
      await expect(page.getByRole("textbox", { name: "Name *" })).toHaveValue(
        name,
      );
    });

    await test.step("It is listed under This facility", async () => {
      await page.goto(basePath);
      await page.getByRole("textbox", { name: "Search ValueSets" }).fill(name);
      await expect(page.getByRole("cell", { name })).toBeVisible();
      await expect(page.getByRole("cell", { name: description })).toBeVisible();
    });
  });

  test("customize an instance value set into a facility override", async ({
    page,
  }) => {
    const parentSlug = "system-nutrients";
    const parentName = "Nutrients";
    const name = `${parentName} for facility ${Date.now()}`;
    await deleteFacilityValueSetsBySlug(facilityId, parentSlug);

    try {
      await test.step("Instance tab offers Preview and Customize per row", async () => {
        await page.getByRole("tab", { name: "Instance" }).click();
        await page
          .getByRole("textbox", { name: "Search ValueSets" })
          .fill(parentName);
        const row = page.getByRole("row").filter({
          has: page.getByRole("cell", { name: parentName, exact: true }),
        });
        await expect(row).toHaveCount(1);
        await expect(row.getByRole("button", { name: "Preview" })).toBeVisible();
        await row.getByRole("button", { name: "Customize" }).click();
        await page.waitForURL(/\/settings\/valuesets\/create\?parent=[0-9a-f-]+$/);
      });

      await test.step("The create form is seeded as an override of the parent", async () => {
        await expect(
          page.getByRole("switch", { name: "Replace the parent in this facility" }),
        ).toBeChecked();
        const slug = page.getByRole("textbox", { name: "Slug *" });
        await expect(slug).toBeDisabled();
        await expect(slug).toHaveValue(parentSlug);
        await expect(
          page.getByRole("combobox").filter({ hasText: parentName }),
        ).toBeVisible();
      });

      await test.step("Naming it does not touch the inherited slug; save", async () => {
        await page.getByRole("textbox", { name: "Name *" }).fill(name);
        await expect(page.getByRole("textbox", { name: "Slug *" })).toHaveValue(
          parentSlug,
        );
        await page.getByRole("button", { name: "Save ValueSet" }).click();
        await expectToast(page, /valueset created successfully/i);
        await page.waitForURL(/\/settings\/valuesets\/[0-9a-f-]+\/edit$/);
      });

      await test.step("The override is listed for this facility under the parent's slug", async () => {
        await page.goto(basePath);
        await page.getByRole("textbox", { name: "Search ValueSets" }).fill(name);
        const row = page.getByRole("row").filter({
          has: page.getByRole("cell", { name, exact: true }),
        });
        await expect(row).toHaveCount(1);
        await expect(row.getByRole("cell", { name: parentSlug })).toBeVisible();
      });
    } finally {
      await deleteFacilityValueSetsBySlug(facilityId, parentSlug);
    }
  });
});

import { adminApiHeaders, apiBaseUrl } from "tests/helper/questionnaireV2";

interface ValueSetSummary {
  id: string;
  slug: string;
  name: string;
}

/** Lists a facility's value sets (every status) through the API. */
export async function listFacilityValueSets(
  facilityId: string,
): Promise<ValueSetSummary[]> {
  const res = await fetch(
    `${apiBaseUrl()}/api/v1/valueset/?facility=${facilityId}&limit=100`,
    { headers: adminApiHeaders() },
  );
  if (!res.ok) {
    throw new Error(`valueset list failed: ${res.status}`);
  }
  const body = (await res.json()) as { results: ValueSetSummary[] };
  return body.results;
}

/**
 * Removes this facility's value sets with `slug`. The backend enforces slug
 * uniqueness per facility and the local DB is not reset between runs, so a
 * spec that creates an override must clear leftovers first and clean up
 * after itself. Soft-deleted rows no longer count towards the constraint.
 */
export async function deleteFacilityValueSetsBySlug(
  facilityId: string,
  slug: string,
): Promise<void> {
  const leftovers = (await listFacilityValueSets(facilityId)).filter(
    (valueset) => valueset.slug === slug,
  );
  for (const valueset of leftovers) {
    await fetch(`${apiBaseUrl()}/api/v1/valueset/${valueset.id}/`, {
      method: "DELETE",
      headers: adminApiHeaders(),
    });
  }
}

/**
 * Creates a facility override of an instance value set: an `inherited`
 * child that takes the parent's slug and adds `codes` (UCUM units here)
 * on top of the parent's composition. Returns the new set's id.
 */
export async function createFacilityOverride({
  facilityId,
  parentId,
  parentSlug,
  name,
}: {
  facilityId: string;
  parentId: string;
  parentSlug: string;
  name: string;
}): Promise<string> {
  const res = await fetch(`${apiBaseUrl()}/api/v1/valueset/`, {
    method: "POST",
    headers: adminApiHeaders(),
    body: JSON.stringify({
      auth_context: "facility",
      facility: facilityId,
      parent: parentId,
      inherited: true,
      name,
      slug: parentSlug,
      description: "Playwright facility override",
      status: "active",
      compose: {
        include: [
          {
            system: "http://unitsofmeasure.org",
            version: null,
            concept: [{ code: "mg", display: "milligram" }],
          },
        ],
        exclude: [],
      },
    }),
  });
  if (!res.ok) {
    throw new Error(
      `valueset create failed: ${res.status} ${await res.text()}`,
    );
  }
  const body = (await res.json()) as { id: string };
  return body.id;
}

/** Resolves an instance value set by slug (the list has no slug filter). */
export async function getInstanceValueSetIdBySlug(
  slug: string,
): Promise<string> {
  const res = await fetch(
    `${apiBaseUrl()}/api/v1/valueset/?auth_context=instance&limit=100`,
    { headers: adminApiHeaders() },
  );
  const body = (await res.json()) as { results: ValueSetSummary[] };
  const match = body.results.find((valueset) => valueset.slug === slug);
  if (!match) {
    throw new Error(`instance value set ${slug} not found`);
  }
  return match.id;
}

import { expect, test, type Page } from "@playwright/test";
import {
  addTopLevelQuestion,
  adminApiHeaders,
  apiBaseUrl,
  createQuestionnaireAndOpenBuilder,
  pickValuesetFromAutocomplete,
} from "tests/helper/questionnaireV2";
import { expectToast } from "tests/helper/ui";
import {
  createFacilityOverride,
  deleteFacilityValueSetsBySlug,
  getInstanceValueSetIdBySlug,
} from "tests/helper/valueSet";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

const PARENT_SLUG = "system-ucum-units";
const PARENT_NAME = "UCUM Units";

/** Picks a question type by its cmdk data-value token. */
async function pickType(page: Page, type: string): Promise<void> {
  await page.getByRole("combobox").first().click();
  await page
    .locator(`[data-slot="command-item"][data-value="${type}"]`)
    .click();
}

interface StoredQuestion {
  text: string;
  answer_value_set?: { slug?: string | null; external_id?: string | null };
}

async function storedQuestion(
  questionnaireId: string,
  text: string,
): Promise<StoredQuestion> {
  const res = await fetch(
    `${apiBaseUrl()}/api/v1/questionnaire/${questionnaireId}/`,
    { headers: adminApiHeaders() },
  );
  const body = (await res.json()) as { questions: StoredQuestion[] };
  const question = body.questions.find((q) => q.text === text);
  if (!question) {
    throw new Error(`question "${text}" not found on ${questionnaireId}`);
  }
  return question;
}

/**
 * The studio's value-set picker inside a facility lists the facility's own
 * sets next to the instance ones, and stores them differently: an instance
 * set by slug alone (so the facility's override and each user's preference
 * apply at fill time), a facility set pinned by id.
 */
test.describe("Studio value-set picker (facility scope)", () => {
  test("labels both scopes and binds instance sets by slug, facility sets by id", async ({
    page,
  }) => {
    const facilityId = getFacilityId();
    const stamp = Date.now();
    const overrideName = `UCUM facility ${stamp}`;
    const questionTitle = `Dose unit ${stamp}`;

    await deleteFacilityValueSetsBySlug(facilityId, PARENT_SLUG);
    const overrideId = await createFacilityOverride({
      facilityId,
      parentId: await getInstanceValueSetIdBySlug(PARENT_SLUG),
      parentSlug: PARENT_SLUG,
      name: overrideName,
    });

    try {
      let questionnaireId = "";

      await test.step("Author a value-set choice question", async () => {
        const detailUrl = await createQuestionnaireAndOpenBuilder(page, {
          basePath: `/facility/${facilityId}/settings/questionnaires`,
          title: `QV2 VS Scope ${stamp}`,
        });
        questionnaireId =
          detailUrl.match(/questionnaires\/([0-9a-f-]+)/)?.[1] ?? "";
        expect(questionnaireId).not.toBe("");

        await addTopLevelQuestion(page, questionTitle);
        await pickType(page, "choice");
        await page.getByRole("radio", { name: "Value Set" }).click();
      });

      await test.step("Picker lists the facility override and the instance set, labelled", async () => {
        await page
          .getByRole("combobox")
          .filter({ hasText: "Select a value set" })
          .click();
        const popover = page
          .locator("[data-radix-popper-content-wrapper]")
          .last();
        await popover
          .locator('[data-slot="command-input"]')
          .first()
          .fill("UCUM");
        await expect(
          popover.getByRole("option", {
            name: `${overrideName} (This facility)`,
          }),
        ).toBeVisible();
        await expect(
          popover.getByRole("option", { name: `${PARENT_NAME} (Instance)` }),
        ).toBeVisible();
        await popover
          .getByRole("option", { name: `${overrideName} (This facility)` })
          .click();
      });

      await test.step("A facility set is stored pinned by id", async () => {
        await page.getByRole("button", { name: "Save Changes" }).click();
        await expectToast(page, "Questionnaire updated successfully");
        const question = await storedQuestion(questionnaireId, questionTitle);
        expect(question.answer_value_set?.external_id).toBe(overrideId);
        expect(question.answer_value_set?.slug).toBe(PARENT_SLUG);
      });

      await test.step("An instance set is stored by slug alone", async () => {
        await pickValuesetFromAutocomplete(page, {
          search: "UCUM",
          optionName: `${PARENT_NAME} (Instance)`,
        });
        await page.getByRole("button", { name: "Save Changes" }).click();
        await expectToast(page, "Questionnaire updated successfully");
        const question = await storedQuestion(questionnaireId, questionTitle);
        expect(question.answer_value_set?.slug).toBe(PARENT_SLUG);
        expect(question.answer_value_set?.external_id ?? null).toBeNull();
      });
    } finally {
      await deleteFacilityValueSetsBySlug(facilityId, PARENT_SLUG);
    }
  });
});

import { expect, test, type Page } from "@playwright/test";
import {
  addTopLevelQuestion,
  createQuestionnaireAndOpenBuilder,
  pickValuesetFromAutocomplete,
  questionBlock,
} from "tests/helper/questionnaireV2";
import { closeAnyOpenPopovers, expectToast } from "tests/helper/ui";
import {
  createFacilityOverride,
  deleteFacilityValueSetsBySlug,
  getInstanceValueSetIdBySlug,
} from "tests/helper/valueSet";
import { getEncounterId } from "tests/support/encounterId";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

const PARENT_SLUG = "system-ucum-units";
const PARENT_NAME = "UCUM Units";

/** Picks a question type by its cmdk data-value token. */
async function pickType(page: Page, type: string): Promise<void> {
  await page.getByRole("combobox").first().click();
  await page
    .locator(`[data-slot="command-item"][data-value="${type}"]`)
    .click();
}

/**
 * A slug-bound choice question resolves its value set per facility: the
 * facility's override of the slug wins over the instance set, and each
 * user can pick either from the search popover. The pick is saved as the
 * user's preference and survives reopening the popover.
 */
test.describe("Fill page: choosing between value-set variants", () => {
  test("the search popover lets the user switch the slug between the facility override and the instance set", async ({
    page,
  }) => {
    const facilityId = getFacilityId();
    const stamp = Date.now();
    const overrideName = `UCUM facility ${stamp}`;
    const questionTitle = `Dose unit ${stamp}`;
    let questionnaireId = "";

    await deleteFacilityValueSetsBySlug(facilityId, PARENT_SLUG);
    await createFacilityOverride({
      facilityId,
      parentId: await getInstanceValueSetIdBySlug(PARENT_SLUG),
      parentSlug: PARENT_SLUG,
      name: overrideName,
    });

    try {
      await test.step("Author a choice question bound to the instance set by slug", async () => {
        const detailUrl = await createQuestionnaireAndOpenBuilder(page, {
          basePath: `/facility/${facilityId}/settings/questionnaires`,
          title: `QV2 VS Preference ${stamp}`,
        });
        questionnaireId =
          detailUrl.match(/questionnaires\/([0-9a-f-]+)/)?.[1] ?? "";
        expect(questionnaireId).not.toBe("");

        await addTopLevelQuestion(page, questionTitle);
        await pickType(page, "choice");
        await page.getByRole("radio", { name: "Value Set" }).click();
        await pickValuesetFromAutocomplete(page, {
          search: "UCUM",
          optionName: `${PARENT_NAME} (Instance)`,
        });
        await page.getByRole("button", { name: "Save Changes" }).click();
        await expectToast(page, "Questionnaire updated successfully");
      });

      await page.goto(
        `/facility/${facilityId}/patient/${getPatientId()}/encounter/${getEncounterId()}/questionnaire/${questionnaireId}`,
      );
      const block = questionBlock(page, questionTitle);
      await expect(block).toHaveCount(1);

      const openPicker = async () => {
        await closeAnyOpenPopovers(page);
        await block.getByRole("combobox").click();
        const dialog = page.getByRole("dialog").last();
        const scope = (await dialog.isVisible().catch(() => false))
          ? dialog
          : page.locator("[data-radix-popper-content-wrapper]").last();
        await expect(scope.getByText(/^Using /)).toBeVisible();
        return scope;
      };

      const choose = async (
        scope: ReturnType<typeof page.locator>,
        optionName: string,
      ) => {
        await scope.getByRole("button", { name: "Change" }).click();
        await page
          .getByRole("listbox", { name: "Choose which value set to search" })
          .getByRole("option", { name: optionName })
          .click();
        await expectToast(page, "Value set preference saved");
      };

      await test.step("Pick the facility override; the popover now searches it", async () => {
        const scope = await openPicker();
        await choose(scope, overrideName);
        await expect(scope.getByText(`Using ${overrideName}`)).toBeVisible();
      });

      await test.step("Pick the instance set; the preference persists across reopen", async () => {
        const scope = await openPicker();
        await choose(scope, PARENT_NAME);
        await expect(scope.getByText(`Using ${PARENT_NAME}`)).toBeVisible();

        const reopened = await openPicker();
        await expect(reopened.getByText(`Using ${PARENT_NAME}`)).toBeVisible();
      });
    } finally {
      await deleteFacilityValueSetsBySlug(facilityId, PARENT_SLUG);
    }
  });
});

