export const meta = {
  name: 'review-valueset-scopes',
  description: 'Multi-lens review of the uncommitted facility value-set changes, each finding adversarially verified',
  phases: [
    { title: 'Review', detail: 'six independent reviewers, one per dimension' },
    { title: 'Verify', detail: 'three distinct-lens skeptics per finding' },
  ],
}

const CONTEXT = `
You are reviewing UNCOMMITTED changes in the git working tree of /Users/bodhishthomas/code/care_fe
(React 19 + TypeScript + Vite frontend for the CARE EMR). Do NOT edit any file — this is a read-only review.

Feature under review: value sets at facility level (backend: care repo branch ENG-737, checked out at
/Users/bodhishthomas/code/care — read backend files with \`git -C /Users/bodhishthomas/code/care show origin/ENG-737:<path>\`,
e.g. care/emr/api/viewsets/valueset.py, care/emr/models/valueset.py, care/emr/resources/valueset/spec.py,
care/security/authorization/valueset.py, care/emr/resources/questionnaire/spec.py, care/emr/resources/questionnaire/utils.py).
The design note is at .superpowers/sdd/2026-09-04-valueset-scopes-design.md — read it first.

How to see the change set:
- Tracked modifications: \`git diff\` (16 files). Read full files, not only hunks, when judging behaviour.
- New untracked files (read them whole): src/components/Questionnaire/ValueSetVariantChooser.tsx,
  src/components/ValueSet/ValueSetOrganizationsField.tsx, src/components/ValueSet/ValueSetParentPicker.tsx,
  src/components/ValueSet/useCanWriteValueSet.ts, src/components/ValueSet/useScopedValueSets.ts,
  tests/helper/valueSet.ts, tests/facility/settings/valuesets/valuesetFacility.spec.ts,
  tests/facility/settings/questionnaires/questionnaireValuesetScope.spec.ts,
  tests/facility/patient/encounter/fill/fillValuesetPreference.spec.ts.
- Project conventions: CLAUDE.md at the repo root; Playwright conventions: tests/PLAYWRIGHT_GUIDE.md.
- Sibling patterns the change mirrors: src/components/QuestionnaireV2/manage/OrganizationsField.tsx,
  src/components/QuestionnaireV2/useCanWriteQuestionnaire.ts, src/types/questionnaire/questionnaire.ts (QuestionnaireScope),
  src/components/QuestionnaireV2/queryKeys.ts.

Known and ACCEPTED (do not report): the backend read spec lacks auth_context/inherited/parent (worked around with two list queries);
submit-time validation on the backend resolves slug-only references to the instance set (backend gap, already listed);
no slug filter on the list endpoint; preview_search ignores parent; a pre-existing react-hooks/set-state-in-effect warning in
SelectOrCreateValueset.tsx and the pre-existing form.watch() compiler warning in ValueSetForm.tsx.

Already verified green: tsc, eslint (0 errors), prettier, production build, the four new Playwright specs and the existing
admin value-set and related studio/fill specs.

Report only findings you can point at with file:line evidence. For each: what is wrong, a concrete failure scenario
(inputs/state → wrong outcome), and the smallest fix. Prefer fewer, real findings over speculative ones. Severity:
critical = data loss/security/crash on a main path; high = wrong behaviour a user will hit; medium = wrong in an edge case or
a maintainability problem that will bite; low = polish.
`

const DIMENSIONS = [
  {
    key: 'correctness',
    prompt: `${CONTEXT}
Dimension: RUNTIME CORRECTNESS. Hunt for: react-hook-form pitfalls (Controller disabled dropping values, defaultValues vs
async initialParent, isDirty gating the submit button, zod superRefine paths), TanStack Query key/invalidation mistakes
(stale currentValueSet, cross-facility cache leakage, disabled queries keeping old data, invalidation prefixes that miss or
over-hit), raviger routing (nested settings router basePath prepending for <Link>/useNavigate, route order, useQueryParams),
state that survives prop changes incorrectly (e.g. SelectOrCreateValueset's currentValueSet when value changes), the
ValueSetVariantChooser footer logic (when it renders, what "current" is, instance variant only loading on open), and
ValueSetList source/status/page query params interactions.`,
  },
  {
    key: 'backend-contract',
    prompt: `${CONTEXT}
Dimension: BACKEND CONTRACT CONFORMANCE. Compare every request the frontend now makes against origin/ENG-737's
ValueSetViewSet, ValueSetCreateSpec/UpdateSpec/ReadSpec, ValueSetFilter, authorization (get_filtered_valuesets,
can_access_facility_valueset), get_closest_valueset, set_slug_preference, get/set_facility_organizations, expand_slug, and the
questionnaire spec's ValueSetConfig/validate_value_set. Check: payload fields and types (inherited/parent/slug on create;
update payload must not carry create-only fields or fields that would fail validation), query params actually supported
(name/status/auth_context/facility), response shapes assumed (e.g. get_facility_organizations {count, results}), 403 cases
the UI assumes are silent, the binding rule (instance → slug only, facility → slug+external_id) against validate_value_set,
what set_slug_preference accepts (facility must match), and whether anything the UI relies on (e.g. is_system_defined on
facility sets, status filtering) matches the backend.`,
  },
  {
    key: 'ux-i18n-a11y',
    prompt: `${CONTEXT}
Dimension: UX, i18n and ACCESSIBILITY, following CLAUDE.md code style (all user-facing strings via i18next in
public/locale/en.json; lucide-react icons; shadcn primitives). Hunt for: hardcoded strings, keys used but missing from
en.json or added but unused, misleading or inconsistent copy (e.g. "ValueSets" vs "value sets"), labels/accessible names
missing on comboboxes/switches/buttons (the parent picker uses aria-labelledby; the Switch sits in a FormField), mobile
layout regressions in ValueSetList (cards vs table, actions), the Customize/Preview affordances, the "Using X · Change"
footer inside a cmdk Command (keyboard/focus interaction, drawer on mobile), read-only states when canWrite is false,
and whether the empty states and hints say the right thing.`,
  },
  {
    key: 'tests',
    prompt: `${CONTEXT}
Dimension: PLAYWRIGHT SPEC QUALITY per tests/PLAYWRIGHT_GUIDE.md. Review the three new specs and tests/helper/valueSet.ts
for: flakiness (toast races, strict-mode collisions, selectors that match multiple elements, reliance on timing), parallel
safety (per-facility slug uniqueness; the specs use different parent slugs: system-nutrients, system-route,
system-ucum-units — check nothing else collides, including with existing specs in tests/), cleanup correctness (finally
blocks, soft-delete semantics, leftover data from the create spec), assumptions about fixture data (admin superuser,
tests/.auth/*.json, getFacilityId/getPatientId/getEncounterId), CI viability (REACT_CARE_API_URL, apiBaseUrl), and
coverage gaps that matter (e.g. departments field mutation, read-only state, admin mount still working, the studio
inline-create sheet in facility scope). Also judge whether assertions actually pin the behaviour they claim.`,
  },
  {
    key: 'permissions-security',
    prompt: `${CONTEXT}
Dimension: PERMISSIONS and DATA SCOPING. Check useCanWriteValueSet against the backend's actual rules (instance writes are
superuser-only — does the admin mount over-promise for a non-superuser with can_write_valueset?; facility writes need the
permission in the facility ROOT organization — what does facility.permissions reflect?), whether a facility mount can ever
show or mutate another facility's sets (query keys include facilityId? list filters?), whether the Instance tab inside a
facility could let a non-superuser attempt an instance edit, whether ValueSetOrganizationsField's silent 403 hides a real
permission problem, whether set_slug_preference can be pointed at a set from another facility, and any place the UI
assumes superuser behaviour from the spec runs (admin is superuser locally). Also check no secrets/tokens leak into
specs or logs.`,
  },
  {
    key: 'simplification',
    prompt: `${CONTEXT}
Dimension: SIMPLIFICATION, REUSE and CONVENTIONS. The maintainer prefers minimal abstraction: no speculative generality,
smallest design covering the shipped requirements. Hunt for: duplicated logic (label suffixing in two places, list-row
rendering duplicated between table and cards, helper duplication between specs and tests/helper), dead or unused exports
(e.g. valueSetOrganizationsKey, ValueSetCreateContext still exported?, scopeCreateContext usage, ValueSetUpdate),
abstractions that don't earn their keep, naming inconsistencies with the questionnaire scope pattern, import ordering
conventions (3rd-party → library → CAREUI → UI → components → hooks → utils → relative; prettier plugin sorts), comments
that describe history instead of behaviour, and anything that could reuse an existing component instead of a new one
(e.g. OrganizationsField pattern, EmptyState from ui/empty-state). Only report what a careful senior reviewer would
actually ask to change before merge.`,
  },
]

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'integer' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          description: { type: 'string' },
          failure_scenario: { type: 'string' },
          evidence: { type: 'string' },
          suggested_fix: { type: 'string' },
        },
        required: ['title', 'file', 'severity', 'description', 'failure_scenario', 'evidence', 'suggested_fix'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    refuted: { type: 'boolean' },
    reasoning: { type: 'string' },
    severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
  },
  required: ['refuted', 'reasoning', 'severity'],
}

const LENSES = [
  {
    key: 'refute',
    prompt: (f) => `${CONTEXT}
You are a skeptic. A reviewer claims the following defect. Try hard to REFUTE it by reading the actual code (and the backend
where relevant). Default to refuted=true if you cannot reproduce the reasoning from the source. Only refuted=false when the
defect is real as stated.

Claim: ${f.title}
File: ${f.file}${f.line ? ':' + f.line : ''}
Description: ${f.description}
Failure scenario: ${f.failure_scenario}
Evidence: ${f.evidence}
Suggested fix: ${f.suggested_fix}`,
  },
  {
    key: 'reproduce',
    prompt: (f) => `${CONTEXT}
Walk the exact failure scenario below step by step through the real code paths (component props, hooks, query keys, backend
viewset behaviour). Write down the state at each step. If at any step the scenario cannot happen as described, or the outcome
is not actually wrong for the user, set refuted=true. Be concrete.

Claim: ${f.title}
File: ${f.file}${f.line ? ':' + f.line : ''}
Description: ${f.description}
Failure scenario: ${f.failure_scenario}
Evidence: ${f.evidence}`,
  },
  {
    key: 'materiality',
    prompt: (f) => `${CONTEXT}
Judge MATERIALITY and SCOPE. Is this finding (a) real, (b) introduced or made worse by THIS change set rather than
pre-existing, (c) something a maintainer would require fixing before merge, and (d) not in the accepted/known list above?
If any of (a)-(d) fails, set refuted=true and say which. Otherwise refuted=false and assign the severity you believe is right.

Claim: ${f.title}
File: ${f.file}${f.line ? ':' + f.line : ''}
Description: ${f.description}
Failure scenario: ${f.failure_scenario}
Evidence: ${f.evidence}
Suggested fix: ${f.suggested_fix}`,
  },
]

const MAX_PER_DIMENSION = 8

const results = await pipeline(
  DIMENSIONS,
  (d) => agent(d.prompt, { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA }),
  async (review, d) => {
    if (!review) { log(`review:${d.key} returned nothing`); return [] }
    let findings = review.findings || []
    if (findings.length > MAX_PER_DIMENSION) {
      log(`review:${d.key}: ${findings.length} findings, verifying the top ${MAX_PER_DIMENSION} by severity — ${findings.length - MAX_PER_DIMENSION} dropped`)
      const rank = { critical: 0, high: 1, medium: 2, low: 3 }
      findings = findings.slice().sort((a, b) => rank[a.severity] - rank[b.severity]).slice(0, MAX_PER_DIMENSION)
    }
    log(`review:${d.key}: verifying ${findings.length} finding(s)`)
    const verified = await parallel(findings.map((f, i) => () =>
      parallel(LENSES.map((lens) => () =>
        agent(lens.prompt(f), { label: `verify:${d.key}#${i + 1}:${lens.key}`, phase: 'Verify', schema: VERDICT_SCHEMA })))
        .then((votes) => {
          const valid = votes.filter(Boolean)
          const upheld = valid.filter((v) => !v.refuted)
          return { ...f, dimension: d.key, votes: valid, upheld: upheld.length, confirmed: upheld.length >= 2,
            severity: upheld.length ? upheld[0].severity : f.severity }
        })))
    return verified.filter(Boolean)
  },
)

const all = results.filter(Boolean).flat()
const confirmed = all.filter((f) => f.confirmed)
const rejected = all.filter((f) => !f.confirmed)
const rank = { critical: 0, high: 1, medium: 2, low: 3 }
confirmed.sort((a, b) => rank[a.severity] - rank[b.severity])
log(`${confirmed.length} confirmed, ${rejected.length} refuted`)
return {
  confirmed: confirmed.map(({ votes, ...f }) => ({ ...f, reasoning: votes.filter((v) => !v.refuted).map((v) => v.reasoning) })),
  rejected: rejected.map((f) => ({ title: f.title, file: f.file, dimension: f.dimension, upheld: f.upheld,
    why: f.votes.filter((v) => v.refuted).map((v) => v.reasoning.slice(0, 300)) })),
}

